import math

def first_Digit(n):
    if n < 0:
        raise ValueError("Input must be a non-negative integer")

    fact = 1
    for i in range(2, n + 1):
        fact *= i
        while fact % 10 == 0:
            fact //= 10

    while fact >= 10:
        fact //= 10

    return math.floor(fact)
```

